```python
"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq
from collections import deque

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


# --- Internal helpers --------------------------------------------------------

def _dijkstra(graph: WeightedGraph, source: int, target: Optional[int] = None):
    """Dijkstra with optional early termination at target.
    Returns (dist, prev)."""
    nodes = graph.nodes
    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}

    if source not in nodes:
        return dist, prev

    dist[source] = 0.0
    heap = [(0.0, source)]
    visited: Set[int] = set()

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)

        if target is not None and u == target:
            break

        for v, w in graph.neighbors(u):
            if v in visited:
                continue
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    return dist, prev


def _reconstruct_path(prev: Dict[int, Optional[int]], target: int) -> List[int]:
    path: List[int] = []
    cur = target
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()
    return path


# --- Public API --------------------------------------------------------------

def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Complexity: O((V+E) log V) using Dijkstra + heap.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist, prev = _dijkstra(graph, source, target)

    if dist[target] == float('inf'):
        return None, []

    path = _reconstruct_path(prev, target)
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Complexity: O((V+E) log V) for Dijkstra, plus path reconstruction.
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist, prev = _dijkstra(graph, source)
    result: Dict[int, Tuple[float, List[int]]] = {}

    for node in nodes:
        if dist[node] == float('inf'):
            continue
        result[node] = (dist[node], _reconstruct_path(prev, node))

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Complexity: O((k + E) log V) with early-stop Dijkstra.
    """
    if k <= 0:
        return []

    nodes = graph.nodes
    if source not in nodes:
        return []

    dist: Dict[int, float] = {source: 0.0}
    heap = [(0.0, source)]
    visited: Set[int] = set()
    result: List[Tuple[int, float]] = []

    while heap and len(result) < k:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)

        if u != source:
            result.append((u, d))
            if len(result) == k:
                break

        for v, w in graph.neighbors(u):
            if v in visited:
                continue
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Complexity: O(V + E) using BFS.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True

    visited: Set[int] = {source}
    q = deque([source])

    while q:
        u = q.popleft()
        for v, _ in graph.neighbors(u):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                q.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Complexity: O(V + E) using BFS/DFS on an undirected view.
    """
    nodes = graph.nodes
    if not nodes:
        return []

    # Build undirected adjacency
    undirected: Dict[int, Set[int]] = {n: set() for n in nodes}
    for edge in graph._edges:
        undirected[edge.src].add(edge.dst)
        undirected[edge.dst].add(edge.src)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for node in nodes:
        if node in visited:
            continue
        comp: Set[int] = set()
        stack = [node]
        visited.add(node)
        while stack:
            u = stack.pop()
            comp.add(u)
            for v in undirected[u]:
                if v not in visited:
                    visited.add(v)
                    stack.append(v)
        components.append(comp)

    return components
